"""Random cross-check of submission vs the naive reference."""
import copy
import json
import random
import sys

sys.path.insert(0, "/workspace/submission")
sys.path.insert(0, "/workspace/tmp/tests")

from main import run_request
from naive_ref import run_reference


def gen_name(rng, used):
    while True:
        n = rng.randint(1, 6)
        first = rng.choice("AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz")
        rest = "AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz0123456789"
        name = first + "".join(rng.choice(rest) for _ in range(n - 1))
        if name not in used:
            used.add(name)
            return name


def gen_topology(rng):
    n = rng.randint(2, 6)
    ids = rng.sample(range(0, 50), n)
    used = set()
    nodes = []
    for nid in ids:
        nodes.append({"id": nid, "name": gen_name(rng, used),
                      "external_capacity": rng.randint(0, 30)})
    links = []
    pairs = set()
    maxlinks = rng.randint(0, min(8, n * (n - 1) // 2))
    deg = {nid: 0 for nid in ids}
    for _ in range(maxlinks):
        a, b = rng.sample(ids, 2)
        key = (min(a, b), max(a, b))
        if key in pairs or deg[a] >= 8 or deg[b] >= 8:
            continue
        pairs.add(key)
        deg[a] += 1
        deg[b] += 1
        links.append({"source": key[0], "target": key[1], "capacity": rng.randint(0, 30)})
    k = rng.randint(1, min(3, n))
    externals = [nodes[i]["name"] for i in rng.sample(range(n), k)]
    return {"nodes": nodes, "links": links, "external_nodes": externals}, nodes, externals


def simple_paths(adj, src, dst, rng, count):
    """Random simple paths from src to dst (node names)."""
    out = []
    attempts = 0
    while len(out) < count and attempts < 60:
        attempts += 1
        path = [src]
        seen = {src}
        ok = False
        while len(path) <= 12:
            if path[-1] == dst:
                ok = True
                break
            nxt = [x for x in adj.get(path[-1], []) if x not in seen]
            if not nxt:
                break
            nxts = rng.choice(nxt)
            path.append(nxts)
            seen.add(nxts)
        if ok and len(path) >= 2 and path[-1] == dst:
            out.append(path)
    if not out:
        out.append([src, dst]) if dst in adj.get(src, []) else None
    return out if out else None


def gen_routes(rng, topo, nodes, externals):
    if rng.random() < 0.25:
        return None
    adj = {}
    name_of = {nd["id"]: nd["name"] for nd in nodes}
    id_of = {nd["name"]: nd["id"] for nd in nodes}
    for l in topo["links"]:
        a, b = name_of[l["source"]], name_of[l["target"]]
        adj.setdefault(a, []).append(b)
        adj.setdefault(b, []).append(a)
    paths = {}
    for s in externals:
        paths[s] = {}
        for d in externals:
            if s == d:
                continue
            cnt = rng.randint(1, 3)
            plist = simple_paths(adj, s, d, rng, cnt)
            if plist is None:
                return None
            # weights summing to 1000
            k = len(plist)
            cuts = sorted(rng.sample(range(1, 1000), k - 1)) if k > 1 else []
            bounds = [0] + cuts + [1000]
            ws = [bounds[i + 1] - bounds[i] for i in range(k)]
            rng.shuffle(ws)
            if any(w < 1 for w in ws):
                return None
            paths[s][d] = [{"path": p, "weight": w} for p, w in zip(plist, ws)]
    return paths


def gen_patch(rng, topo, nodes, externals):
    ev = {"op": "patch"}
    demands = []
    ext_ids = sorted({nd["id"] for nd in nodes if nd["name"] in externals})
    for _ in range(rng.randint(0, 4)):
        s, d = rng.sample(ext_ids, 2) if len(ext_ids) >= 2 else (ext_ids[0], ext_ids[0])
        demands.append([s, d, rng.randint(0, 40)])
    if rng.random() < 0.15 and len(demands) >= 2:
        demands.append(list(demands[0]))  # duplicate pair -> reject
    ev["demands"] = demands
    counters = {}
    name_of = {nd["id"]: nd["name"] for nd in nodes}
    cap = {}
    for l in topo["links"]:
        cap[(l["source"], l["target"])] = cap[(l["target"], l["source"])] = l["capacity"]
    keys = []
    for l in topo["links"]:
        a, b = name_of[l["source"]], name_of[l["target"]]
        keys += ["low_%s_egress_to_%s" % (a, b), "low_%s_ingress_from_%s" % (b, a)]
    ext_cap = {nd["name"]: nd["external_capacity"] for nd in nodes}
    for e in externals:
        keys += ["low_%s_origination" % e, "low_%s_termination" % e]
    for k in keys:
        if rng.random() < 0.5:
            continue
        r = rng.random()
        if r < 0.15:
            counters[k] = None
        else:
            cell = {"perturbed": rng.randint(0, 40) if rng.random() < 0.85 else None}
            if rng.random() < 0.4:
                cell["ground_truth"] = rng.choice([1, "x", None, [1, 2]])
            if rng.random() < 0.3:
                cell["corrected"] = {"a": 1}
            if rng.random() < 0.2:
                cell["confidence"] = 3.5
            counters[k] = cell
    ev["counters"] = counters
    # occasional corruption
    r = rng.random()
    if r < 0.05:
        ev["counters"]["low_bogus"] = {"perturbed": 1}
    elif r < 0.08:
        ev["extra"] = 1
    elif r < 0.10:
        ev["demands"] = "oops"
    elif r < 0.12:
        ev["demands"] = [[1, True, 2]] if ext_ids else [[0, 0, 1]]
    elif r < 0.14:
        ev["counters"] = {keys[0] if keys else "x": {"perturbed": True}}
    elif r < 0.16:
        ev["counters"] = {keys[0] if keys else "x": 5}
    elif r < 0.18:
        ev.pop("demands", None)
    return ev


def gen_request(rng):
    topo, nodes, externals = gen_topology(rng)
    settings = {
        "trials": rng.randint(1, 5),
        "epsilon": rng.choice([0, 0, 100, 10000, 250000]),
        "seed": rng.randint(0, 100),
        "cutoff": [rng.randint(0, 3), rng.randint(1, 4)],
        "bias": rng.choice([0, 0, 5000, 1000000]),
        "tau": rng.choice([0, 0, 1000, 500000]),
        "gamma": [rng.randint(0, 2), rng.randint(1, 3)],
        "cache_slots": rng.randint(0, 3),
    }
    events = []
    ids = ["s1", "s2", "s3"]
    created = []
    for _ in range(rng.randint(1, 10)):
        r = rng.random()
        if r < 0.35:
            events.append(gen_patch(rng, topo, nodes, externals))
        elif r < 0.55:
            events.append({"op": "routes", "label": "L%d" % rng.randint(0, 99),
                           "paths": gen_routes(rng, topo, nodes, externals)})
        elif r < 0.85:
            rid = rng.choice(ids)
            created.append(rid)
            events.append({"op": "repair", "id": rid})
        else:
            if created:
                events.append({"op": "validate", "id": rng.choice(created)})
            else:
                events.append({"op": "repair", "id": rng.choice(ids)})
    return {"streams": [{"topology": topo, "settings": settings, "events": events}]}


def main():
    seed0 = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 500
    bad = 0
    for it in range(rounds):
        rng = random.Random(seed0 + it)
        req = gen_request(rng)
        a = json.loads(json.dumps(run_request(copy.deepcopy(req))))
        b = json.loads(json.dumps(run_reference(copy.deepcopy(req))))
        if a != b:
            bad += 1
            print("MISMATCH at iteration", it)
            print(json.dumps(req))
            print("mine:", json.dumps(a))
            print("ref :", json.dumps(b))
            if bad > 3:
                return 1
    print("checked", rounds, "mismatches", bad)
    return 0 if bad == 0 else 1


if __name__ == "__main__":
    sys.exit(main())
